from pathlib import Path
import re,math,xml.etree.ElementTree as ET
import numpy as np
from statistics import NormalDist
D=NormalDist(); ns={'s':'http://www.w3.org/2000/svg'}
for stem in ['detection-statistic','integration-retention','rejection-information','reference-leakage']:
 root=ET.parse(Path('book/figures')/(stem+'.svg')).getroot()
 paths=[]
 for e in root.findall('s:path',ns):
  pts=[tuple(map(float,v)) for v in re.findall(r'[ML](-?[\\d.]+),(-?[\\d.]+)',e.get('d',''))]
  if len(pts)>100: paths.append((e.get('stroke'),pts))
 errors=[]
 for color,pts in paths:
  for xp,yp in pts:
   if stem=='detection-statistic':
    x=-4+(xp-100)/780*12; y=(652-yp)/195*.44
    expected=D.pdf(x if color=='#125b86' else x-math.sqrt(32*26/101))
   elif stem=='integration-retention':
    x=(xp-100)/780*math.pi; y=(667-yp)/195*1.05
    expected=1 if abs(x)<1e-12 else (math.sin(2*x)/(4*math.sin(x/2)))**2
   elif stem=='rejection-information':
    x=(xp-100)/780*math.pi/2; y=(692-yp)/195*1.05
    b=np.array([math.cos(x),math.sin(x)]); C=np.eye(2)+100*np.outer(b,b); a=np.array([1.,0.])
    if color=='#125b86': expected=float(a@np.linalg.solve(C,a))
    elif color=='#b34719': expected=math.sin(x)**2
    else: expected=1/float(C[0,0])
   else:
    x=(xp-100)/780; y=-(yp-537)/195*48
    h=100/101; s=1.; wanted=(s+0+0)-h*(0+x*s+0)
    expected=10*math.log10(wanted*wanted)
   errors.append(abs(y-expected))
 print(stem,'curves',len(paths),'points',sum(len(p) for _,p in paths),'max_axis_error',max(errors))
# Confirm paired figure assets are identical, without regenerating them.
for p in sorted(Path('book/figures').glob('*.svg')):
 print('book/rendered_identical',p.name,p.read_bytes()==(Path('rendered/figures')/p.name).read_bytes())
